"""OpenAI/Anthropic AI integration template — generates services/ai_client.py."""
from __future__ import annotations


def generate_ai_client(output_dir=None, config: dict | None = None) -> str:
    """Return production-ready AI client code (OpenAI or Anthropic) as a string."""
    return '''\
"""AI client (OpenAI / Anthropic) — generated by AetherOS p04c_integration_codegen.

Auto-detects provider from environment:
  - OPENAI_API_KEY   → uses openai SDK
  - ANTHROPIC_API_KEY → uses anthropic SDK
If both are set, OpenAI takes precedence.
"""
from __future__ import annotations
import asyncio
import logging
import os
from functools import partial
from typing import Any, AsyncIterator, Dict, List, Optional

logger = logging.getLogger(__name__)

_OPENAI_KEY = os.getenv("OPENAI_API_KEY", "")
_ANTHROPIC_KEY = os.getenv("ANTHROPIC_API_KEY", "")
_PROVIDER = "openai" if _OPENAI_KEY else ("anthropic" if _ANTHROPIC_KEY else "none")

_DEFAULT_MODEL_OPENAI = os.getenv("AI_MODEL", "gpt-4o-mini")
_DEFAULT_MODEL_ANTHROPIC = os.getenv("AI_MODEL", "claude-3-5-haiku-20241022")


class AIError(Exception):
    """Base error for AI operations."""


class AIClient:
    """Unified async AI client supporting OpenAI and Anthropic providers."""

    def __init__(self) -> None:
        self._provider = _PROVIDER
        if self._provider == "none":
            logger.warning("No AI API key found — set OPENAI_API_KEY or ANTHROPIC_API_KEY")

    def _openai(self):
        try:
            from openai import OpenAI
            return OpenAI(api_key=_OPENAI_KEY)
        except ImportError as exc:
            raise AIError("openai package not installed: pip install openai") from exc

    def _anthropic(self):
        try:
            import anthropic
            return anthropic.Anthropic(api_key=_ANTHROPIC_KEY)
        except ImportError as exc:
            raise AIError("anthropic package not installed: pip install anthropic") from exc

    async def complete(self, prompt: str, max_tokens: int = 500, temperature: float = 0.7) -> str:
        """Single-turn completion. Returns the assistant text."""
        messages = [{"role": "user", "content": prompt}]
        result = await self.chat(messages, max_tokens=max_tokens, temperature=temperature)
        return result.get("content", "")

    async def embed(self, text: str) -> List[float]:
        """Return a float embedding vector for the given text (OpenAI only)."""
        if self._provider != "openai":
            raise AIError("Embeddings only supported with OpenAI provider")
        try:
            client = self._openai()
            loop = asyncio.get_event_loop()
            resp = await loop.run_in_executor(
                None,
                partial(client.embeddings.create, model="text-embedding-3-small", input=text),
            )
            return resp.data[0].embedding
        except Exception as exc:
            logger.warning("embed failed: %s", exc)
            raise AIError(str(exc)) from exc

    async def chat(
        self,
        messages: List[Dict[str, str]],
        max_tokens: int = 500,
        temperature: float = 0.7,
        system: str = "",
    ) -> Dict[str, Any]:
        """Multi-turn chat. Returns dict with 'content' and 'usage' keys."""
        if self._provider == "openai":
            return await self._chat_openai(messages, max_tokens, temperature, system)
        if self._provider == "anthropic":
            return await self._chat_anthropic(messages, max_tokens, temperature, system)
        raise AIError("No AI provider configured")

    async def _chat_openai(self, messages, max_tokens, temperature, system):
        try:
            client = self._openai()
            full_messages = []
            if system:
                full_messages.append({"role": "system", "content": system})
            full_messages.extend(messages)
            loop = asyncio.get_event_loop()
            resp = await loop.run_in_executor(
                None,
                partial(
                    client.chat.completions.create,
                    model=_DEFAULT_MODEL_OPENAI,
                    messages=full_messages,
                    max_tokens=max_tokens,
                    temperature=temperature,
                ),
            )
            return {
                "content": resp.choices[0].message.content,
                "usage": dict(resp.usage) if resp.usage else {},
            }
        except Exception as exc:
            logger.warning("openai.chat failed: %s", exc)
            raise AIError(str(exc)) from exc

    async def _chat_anthropic(self, messages, max_tokens, temperature, system):
        try:
            client = self._anthropic()
            loop = asyncio.get_event_loop()
            kwargs: Dict[str, Any] = dict(
                model=_DEFAULT_MODEL_ANTHROPIC,
                max_tokens=max_tokens,
                temperature=temperature,
                messages=messages,
            )
            if system:
                kwargs["system"] = system
            resp = await loop.run_in_executor(None, partial(client.messages.create, **kwargs))
            return {
                "content": resp.content[0].text if resp.content else "",
                "usage": {"input_tokens": resp.usage.input_tokens, "output_tokens": resp.usage.output_tokens},
            }
        except Exception as exc:
            logger.warning("anthropic.chat failed: %s", exc)
            raise AIError(str(exc)) from exc

    async def stream_chat(
        self, messages: List[Dict[str, str]], system: str = "", max_tokens: int = 1000,
    ) -> AsyncIterator[str]:
        """Yield text chunks from a streaming AI response."""
        if self._provider == "openai":
            client = self._openai()
            full_messages = ([{"role": "system", "content": system}] if system else []) + messages
            try:
                loop = asyncio.get_event_loop()
                stream = await loop.run_in_executor(
                    None,
                    partial(
                        client.chat.completions.create,
                        model=_DEFAULT_MODEL_OPENAI,
                        messages=full_messages,
                        max_tokens=max_tokens,
                        stream=True,
                    ),
                )
                for chunk in stream:
                    if chunk.choices and chunk.choices[0].delta.content:
                        yield chunk.choices[0].delta.content
            except Exception as exc:
                logger.warning("stream_chat (openai) failed: %s", exc)
                raise AIError(str(exc)) from exc
        elif self._provider == "anthropic":
            raise AIError("Anthropic streaming requires httpx async client — use chat() instead")
        else:
            raise AIError("No AI provider configured")


ai_client = AIClient()
'''
